const paths={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',briefcase:'M8 6V4h8v2M3 7h18v13H3zM3 12c6 3 12 3 18 0M10 12h4v3h-4z',sparkles:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7zM20 2v4M18 4h4',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',pin:'M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 1 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',bookmark:'M6 3h12v18l-6-4-6 4z',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',shield:'m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M12 6v6l4 2',coin:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M6 8l2 8 4-8 4 8 2-8M5 11h14',file:'M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6',edit:'m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14z',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',message:'M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4',building:'M5 22V2h14v20M2 22h20M9 6h1M14 6h1M9 10h1M14 10h1M9 14h1M14 14h1M10 22v-4h4v4',tool:'m14 6 4 4 4-4a7 7 0 0 1-9 9l-7 7-4-4 7-7a7 7 0 0 1 9-9z',plus:'M12 5v14M5 12h14',send:'m22 2-7 20-4-9-9-4zM22 2 11 13'};
