const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baseJobs=[
 {id:'j1',company:'한빛에너지',logo:'H',color:'#164a80',bg:'#e8f0f8',title:'전기 설비 유지보수 엔지니어',role:'전기·설비',region:'경기',location:'경기 수원시',years:3,salary:4800,type:'정규직',skills:['전기설비','시설관리','도면해독'],certs:['전기기능사'],tags:['주 5일','식사 제공','자격수당'],description:'생산 시설의 전기 설비 점검과 예방 정비를 담당합니다. 도면을 읽고 설비의 이상 원인을 함께 해결할 현장 전문가를 찾습니다.',deadline:'상시 채용'},
 {id:'j2',company:'태성엔지니어링',logo:'TS',color:'#366557',bg:'#e8f3ed',title:'생산시설 전기·공무 담당자',role:'전기·설비',region:'경기',location:'경기 화성시',years:2,salary:4500,type:'정규직',skills:['전기설비','시설관리','PLC'],certs:['전기기능사'],tags:['통근버스','교육 지원','주간 근무'],description:'제조 현장의 안정적인 운영을 위한 전기 및 공무 업무입니다. PLC 기초 지식과 전기 설비 유지보수 경험을 우대합니다.',deadline:'상시 채용'},
 {id:'j3',company:'그린빌드',logo:'gb',color:'#55633b',bg:'#f0f3e5',title:'신축 현장 전기 시공 기술자',role:'전기·설비',region:'서울',location:'서울 강서구',years:5,salary:5200,type:'계약직',skills:['전기설비','배선작업','도면해독'],certs:['전기기능사'],tags:['현장수당','중식 제공','장기 프로젝트'],description:'건축 현장의 배선과 전기 시공을 담당합니다. 현장 안전 수칙을 준수하고 팀과 협업할 숙련 기술자를 모집합니다.',deadline:'상시 채용'},
 {id:'j4',company:'원진메탈',logo:'W',color:'#795645',bg:'#f4ece7',title:'정밀 TIG 용접 전문가',role:'용접·금속',region:'경기',location:'경기 시흥시',years:3,salary:5000,type:'정규직',skills:['TIG용접','도면해독','금속가공'],certs:['용접기능사'],tags:['기숙사','주 5일','성과급'],description:'스테인리스 정밀 부품을 가공하고 TIG 용접을 수행합니다. 도면 해독 및 용접 품질 관리 경험을 우대합니다.',deadline:'상시 채용'},
 {id:'j5',company:'넥스트로지스',logo:'N',color:'#65519b',bg:'#f0ecfa',title:'물류센터 지게차 운전원',role:'물류·운송',region:'인천',location:'인천 서구',years:1,salary:3800,type:'정규직',skills:['지게차운전','재고관리','입출고'],certs:['지게차운전기능사'],tags:['식사 제공','통근버스','교대 근무'],description:'물류센터의 입출고와 적재 업무를 수행합니다. 지게차 자격과 안전 운행 경험이 필요합니다.',deadline:'상시 채용'},
 {id:'j6',company:'우드앤웍스',logo:'ww',color:'#8b6747',bg:'#f7efe5',title:'인테리어 현장 목공 기술자',role:'건설·시공',region:'서울',location:'서울 성동구',years:2,salary:4200,type:'정규직',skills:['목공','도면해독','인테리어시공'],certs:['건축목공기능사'],tags:['장비 지원','주 5일','교육 지원'],description:'주거 및 상업 공간의 목공 시공을 담당합니다. 정확한 도면 이해와 꼼꼼한 마감 역량을 우대합니다.',deadline:'상시 채용'}
];
const initial={profile:{name:'김민준',role:'전기·설비',years:5,region:'경기',salary:4200,skills:['전기설비','시설관리','도면해독'],certs:['전기기능사'],bio:'5년간 생산 현장의 전기 설비를 관리했습니다. 안전하고 안정적인 현장을 만드는 일을 좋아합니다.'},jobs:[],saved:[],applications:[],posts:[],likes:[],comments:{}};
let state=structuredClone(initial);try{const saved=JSON.parse(localStorage.getItem('bluein-v1'));if(saved&&saved.profile&&Array.isArray(saved.jobs)&&Array.isArray(saved.saved)){state={...state,...saved,profile:{...initial.profile,...saved.profile}};}}catch{}
let view=['home','jobs','match','community','saved','applications','employer'].includes(location.hash.slice(1))?location.hash.slice(1):'home';let filter='전체';let query='';let apiReady=false;let aiResults=null;let busy=false;let matchRevision=0;
const jobs=()=>[...state.jobs,...baseJobs];
function persist(){try{localStorage.setItem('bluein-v1',JSON.stringify(state));}catch{toast('저장 공간을 사용할 수 없어 이번 화면에서만 유지됩니다.');}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
function score(job,p=state.profile){const ratio=(a,b)=>b.length?b.filter(s=>a.some(x=>x.trim().toLowerCase()===s.trim().toLowerCase())).length/b.length:1;const parts={기술:Math.round(ratio(p.skills,job.skills)*35),자격증:Math.round(ratio(p.certs,job.certs)*20),경력:Math.round(Math.min(1,p.years/Math.max(job.years,1))*20),지역:p.region===job.region?15:p.region==='전국'?15:0,연봉:Math.round(Math.min(1,job.salary/Math.max(p.salary,1))*10)};const reasons=[];if(parts.기술===35)reasons.push('요구 기술이 모두 일치합니다.');else reasons.push(`요구 기술 ${job.skills.length}개 중 ${job.skills.filter(s=>p.skills.includes(s)).length}개가 일치합니다.`);if(parts.자격증===20)reasons.push(job.certs.length?'요구 자격증을 보유하고 있습니다.':'필수 자격증 조건이 없습니다.');else reasons.push(`확인이 필요한 자격증: ${job.certs.filter(s=>!p.certs.includes(s)).join(', ')}`);if(p.years>=job.years)reasons.push(`경력 ${p.years}년으로 요구 경력 ${job.years}년을 충족합니다.`);else reasons.push(`요구 경력보다 ${job.years-p.years}년 적습니다.`);if(parts.지역===0)reasons.push('희망 근무 지역과 달라 이동 가능 여부를 확인해 주세요.');return {id:job.id,score:Object.values(parts).reduce((a,b)=>a+b,0),parts,reasons};}
function result(job){return aiResults?.find(r=>r.id===job.id)||score(job);}
function ranked(){return jobs().map(j=>({...j,result:result(j)})).sort((a,b)=>b.result.score-a.result.score);}
function navigate(next){view=next;filter='전체';query='';document.getElementById('search').value='';history.replaceState(null,'',`#${next}`);render();window.scrollTo({top:0,behavior:'smooth'});}
function render(){renderSidebar();renderRight();document.querySelectorAll('.main-nav [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});document.querySelector('.top-profile').textContent=state.profile.name.slice(-2,-1)||'나';const main=document.getElementById('main');if(view==='home')main.innerHTML=home();else if(view==='jobs'||view==='saved'||view==='applications')main.innerHTML=jobPage();else if(view==='match')main.innerHTML=matchPage();else if(view==='community')main.innerHTML=community();else if(view==='employer')main.innerHTML=employer();document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function renderSidebar(){const p=state.profile;document.getElementById('sidebar').innerHTML=`<section class="card"><div class="profile-cover"></div><div class="profile-body"><div class="avatar profile-avatar">${esc(p.name.slice(-2))}</div><div class="name-line"><h2>${esc(p.name)}</h2><span class="verified">${icon('shield')}</span></div><p class="profile-title">${esc(p.role)} 전문가 · 경력 ${p.years}년</p><p class="meta">${icon('pin')}${esc(p.region)} 지역</p><span class="available">새로운 기회를 찾고 있어요</span></div><div class="profile-progress"><div class="between small"><span>나의 프로필</span><b class="blue">${p.bio&&p.certs.length?'100':'85'}%</b></div><div class="progress"><span style="width:${p.bio&&p.certs.length?100:85}%"></span></div><button class="text-link" data-action="profile">프로필 업데이트 ${icon('arrow')}</button></div></section><nav class="card side-menu" aria-label="내 커리어">${[['home','home','내 피드'],['match','sparkles','AI 맞춤 매칭'],['saved','bookmark','저장한 채용'],['applications','file','지원 내역']].map(([v,i,l])=>`<button data-view="${v}" class="${view===v?'active':''}">${icon(i)}${l}${v==='saved'?`<span class="count">${state.saved.length}</span>`:''}</button>`).join('')}</nav><div class="side-note"><span class="eyebrow">YOUR SKILL, YOUR FUTURE</span><h3>당신의 기술이<br>더 좋은 기회를 만듭니다.</h3><p>현장에서 쌓은 경험이<br>제대로 인정받는 곳, 블루인.</p></div>`;}
function renderRight(){const high=ranked().filter(j=>j.result.score>=75).length;document.getElementById('rightbar').innerHTML=`<section class="card right-card match-summary"><h2>${icon('sparkles')}나의 매칭 현황</h2><p>내 기술과 경험에 맞는 새로운 기회</p><div class="summary-stats"><div><strong class="blue">${high}</strong><small>추천 채용</small></div><div><strong>${state.applications.length}</strong><small>관심 지원</small></div></div><p class="summary-hint">${icon('check')} 프로필을 바꾸면 매칭도 달라져요</p><button class="secondary full" data-view="match">맞춤 채용 확인하기 ${icon('arrow')}</button></section><section class="card right-card"><h2>현장에서 찾는 기술</h2><p>등록된 예시 공고의 주요 직무</p><ol class="trending-list">${[['전기·설비','전기설비 · 시설관리','01'],['용접·금속','TIG용접 · 금속가공','02'],['물류·운송','지게차운전 · 입출고','03'],['건설·시공','목공 · 인테리어시공','04']].map(([r,t,n])=>`<li><span class="rank">${n}</span><div><strong>${r}</strong><small>${t}</small></div><span class="trend-tag">모집</span></li>`).join('')}</ol></section><section class="employer-promo">${icon('building')}<h3>우리 현장에 딱 맞는 전문가,<br>어디서 찾고 계신가요?</h3><p>필요한 기술과 채용 조건을 등록하고<br>맞는 인재를 만나보세요.</p><button class="secondary full" data-view="employer">기업 채용 등록 ${icon('arrow')}</button></section><div class="footer-links">현장의 기술과 사람을 연결합니다.<br>프로필과 작성 내용은 이 브라우저에 저장됩니다.<div class="brand-small">bluein <span class="local-label">로컬 데모</span></div><p>© 2026 Bluein. All rights reserved.</p></div>`;}
function chips(){return `<div class="filter-row" aria-label="직무 필터">${['전체','전기·설비','용접·금속','물류·운송','건설·시공'].map(x=>`<button class="chip ${filter===x?'active':''}" data-filter="${x}" aria-pressed="${filter===x}">${x}</button>`).join('')}</div>`;}
function jobCard(j){const r=result(j);return `<article class="card job-card"><div class="job-top"><div class="company-logo" style="background:${j.bg};color:${j.color}">${esc(j.logo)}</div><div><div class="company-name">${esc(j.company)} ${icon('building')}</div><button class="job-title" data-detail="${esc(j.id)}">${esc(j.title)}</button></div><button class="bookmark ${state.saved.includes(j.id)?'saved':''}" data-save="${esc(j.id)}" aria-label="${state.saved.includes(j.id)?'저장 취소':'채용 저장'}" aria-pressed="${state.saved.includes(j.id)}">${icon('bookmark')}</button></div><div class="job-meta"><span>${icon('pin')}${esc(j.location)}</span><span>${icon('briefcase')}경력 ${j.years}년 이상</span><span>${icon('coin')}연 ${Number(j.salary).toLocaleString()}만 원</span></div><div class="tags"><span class="tag">${esc(j.type)}</span>${j.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="job-bottom"><button class="match-badge" data-detail="${esc(j.id)}">${icon('sparkles')}${aiResults?'AI':'조건'} 매칭 ${r.score}% <span>${r.score>=75?'내 경험과 잘 맞아요':'매칭 이유 확인'}</span></button><span class="deadline">${state.applications.includes(j.id)?'관심 지원 기록됨':esc(j.deadline)}</span></div></article>`;}
function filtered(){return ranked().filter(j=>(filter==='전체'||j.role===filter)&&(!query||[j.title,j.company,j.location,...j.skills,...j.certs].join(' ').toLowerCase().includes(query.toLowerCase())));}
function empty(title='조건에 맞는 채용이 없어요',text='다른 검색어나 직무를 선택해 보세요.'){return `<div class="card empty">${icon('search')}<h3>${title}</h3><p>${text}</p><button class="secondary" data-view="jobs">전체 채용 보기</button></div>`;}
function home(){return `<div class="welcome"><div><h1>${esc(state.profile.name)}님, 반가워요 👋</h1><p>오늘도 당신의 기술이 빛날 새로운 기회를 만나보세요.</p></div><span class="date-label">${new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short'}).format(new Date())}</span></div><section class="hero"><div class="eyebrow">${icon('sparkles')} BLUEIN MATCH</div><h2>이력서 너머의 실력,<br>딱 맞는 현장과 연결되다.</h2><p>당신이 쌓아온 기술과 경험으로<br>다음 커리어를 찾아보세요.</p><button class="primary" data-view="match">나에게 맞는 채용 보기 ${icon('arrow')}</button><div class="hero-orbit" aria-hidden="true"><span class="orbit-badge one">${icon('shield')}</span><div class="core">${icon('sparkles')}</div><span class="orbit-badge two">${icon('briefcase')}</span></div></section><section><div class="section-header"><h2>${icon('sparkles')}나를 위한 추천 채용</h2><button class="text-link" data-view="jobs">전체 보기 →</button></div>${chips()}<div class="job-list">${filtered().slice(0,3).map(jobCard).join('')||empty()}</div></section><section><div class="section-header"><h2>현장 이야기</h2><button class="text-link" data-view="community">더 보기 →</button></div>${feedCard(samplePosts[0])}</section>`;}
function jobPage(){let list=filtered();let title='기술이 기회가 되는 채용';let subtitle='경험을 알아보는 기업을 만나보세요.';if(view==='saved'){list=list.filter(j=>state.saved.includes(j.id));title='저장한 채용';subtitle='눈여겨본 기회들을 한곳에 모았어요.';}if(view==='applications'){list=list.filter(j=>state.applications.includes(j.id));title='관심 지원 내역';subtitle='이 브라우저에 기록한 관심 지원입니다. 기업에 실제 전송되지 않습니다.';}return `<div class="page-heading"><h1>${title}</h1><p>${subtitle}</p></div>${chips()}<div class="section-header"><span class="small muted">${query?`“${esc(query)}” 검색 · `:''}총 ${list.length}개 채용 · 매칭순</span><span class="small muted">예시 기업 및 채용 포함</span></div><div class="job-list">${list.map(jobCard).join('')||empty(view==='saved'?'저장한 채용이 아직 없어요':view==='applications'?'아직 관심 지원 내역이 없어요':undefined,view==='saved'?'마음에 드는 채용의 북마크를 눌러보세요.':undefined)}</div>`;}
function matchPage(){return `<div class="page-heading"><h1>나의 다음 현장, AI 매칭</h1><p>기술과 경험을 바탕으로 나에게 맞는 기회를 찾습니다.</p></div><section class="card match-intro"><div class="between"><h2>${icon('sparkles')} ${esc(state.profile.name)}님의 커리어 매칭</h2><button class="text-link" data-action="profile">프로필 수정</button></div><p>${esc(state.profile.role)} · 경력 ${state.profile.years}년 · ${esc(state.profile.region)} · 희망 연봉 ${state.profile.salary.toLocaleString()}만 원</p><div class="tags" style="margin-top:14px">${[...state.profile.skills,...state.profile.certs].map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div><button class="primary full" data-action="match" ${busy?'disabled':''}>${icon('sparkles')}${busy?'분석하고 있어요…':apiReady?'AI로 매칭 분석하기':'내 조건으로 다시 매칭하기'}</button><div class="mode-line">${apiReady?'AI 분석 시 이름을 제외한 경력·기술·채용 조건을 OpenAI에 전송합니다.':'조건 매칭 모드 · 기술 35% / 자격증 20% / 경력 20% / 지역 15% / 연봉 10%'}<br>점수는 참고용이며 합격 가능성을 의미하지 않습니다.</div></section><div class="section-header"><h2>추천 채용 ${jobs().length}<span class="local-label">${aiResults?'AI 분석 완료':'조건 기반'}</span></h2></div><div class="job-list">${busy?'<div class="card loading"><span class="spinner"></span><p>경험과 채용 조건을 비교하고 있습니다.</p></div>':ranked().map(jobCard).join('')}</div>`;}
const samplePosts=[{id:'p1',author:'블루인 커뮤니티',role:'현장 전문가들의 커리어 노트',text:'자격증 한 줄보다, 현장에서 배운 한 가지.\n첫 현장에 나갔던 날 기억하시나요? 도면 밖에서 배운 기술, 함께 일하며 익힌 노하우를 들려주세요.',title:'경험이 실력이 되는 순간',art:true,likes:24},{id:'p2',author:'박정우',role:'용접·금속 · 경력 12년 · 예시 프로필',text:'후배들에게 늘 하는 말이 있습니다. 작업 속도보다 중요한 건 기본을 지키는 습관이라고요. 오늘도 작업 전에 장비를 한 번 더 점검했습니다. 모두 안전한 하루 보내세요!',likes:18}];
function feedCard(p){return `<article class="card"><div class="feed-header"><div class="avatar" style="${p.id==='p1'?'background:#eaf0fe;color:#265ee8':''}">${p.id==='p1'?'b':esc(p.author.slice(-2))}</div><div><div class="feed-author">${esc(p.author)}</div><div class="small muted">${esc(p.role||'나의 현장 이야기')}</div></div><span class="local-label" style="margin-left:auto">${p.id.startsWith('p')?'예시':'내 글'}</span></div><div class="feed-content">${p.title?`<h3>${esc(p.title)}</h3>`:''}${esc(p.text)}</div>${p.art?'<div class="feed-art"><div><small>BUILT BY EXPERIENCE</small><strong>현장의 경험은<br>누구도 대신할 수 없으니까.</strong></div><div class="big-number">01<span style="font-size:18px"> /</span></div></div>':''}<div class="feed-actions"><button data-like="${p.id}" class="${state.likes.includes(p.id)?'liked':''}">${icon('heart')}공감 ${(p.likes||0)+(state.likes.includes(p.id)?1:0)}</button><button data-comments="${p.id}">${icon('message')}댓글 ${(state.comments[p.id]||[]).length}</button></div><div id="comments-${p.id}" hidden class="comments">${(state.comments[p.id]||[]).map(c=>`<p class="comment-row"><b>${esc(c.author)}</b> ${esc(c.text)}</p>`).join('')}<form class="comment-form" data-comment-form="${p.id}"><input name="comment" placeholder="따뜻한 한마디를 남겨주세요" aria-label="댓글" maxlength="500" required><button class="secondary" type="submit">등록</button></form></div></article>`;}
function community(){return `<div class="page-heading"><h1>현장 이야기</h1><p>같은 일을 하는 사람들과 경험을 나누세요.</p></div><div class="notice">로컬 커뮤니티 데모입니다. 글과 댓글은 현재 브라우저에만 저장됩니다.</div><div class="card compose"><div class="avatar">${esc(state.profile.name.slice(-2))}</div><button data-action="write">오늘 현장에서는 어떤 일이 있었나요?</button></div>${[...state.posts,...samplePosts].map(feedCard).join('')}`;}
const roles=['전기·설비','용접·금속','물류·운송','건설·시공','정비·제조','기타'];const regions=['서울','경기','인천','부산','대구','광주','대전','울산','세종','강원','충북','충남','전북','전남','경북','경남','제주'];
const options=(list,selected)=>list.map(v=>`<option ${v===selected?'selected':''}>${v}</option>`).join('');
function field(label,name,value,type='text',extra=''){return `<label class="field ${extra}">${label}<input name="${name}" value="${esc(value)}" type="${type}" ${type==='number'?'min="0" max="100000" step="1"':'maxlength="120"'} required></label>`;}
function employer(){return `<div class="page-heading"><h1>기술을 알아보는 채용</h1><p>우리 현장에 필요한 조건을 알려주세요.</p></div><div class="notice">기업 채용 등록 데모 · 등록한 공고는 이 브라우저의 채용 목록과 매칭에 즉시 반영됩니다.</div><form id="employer-form" class="card form-card"><h2 style="font-size:18px;margin-bottom:20px">새 채용 등록</h2><div class="form-grid">${field('기업명','company','')}${field('채용 제목','title','')}<label class="field">직무<select name="role">${options(roles,'전기·설비')}</select></label><label class="field">근무 지역<select name="region">${options(regions,'경기')}</select></label>${field('최소 경력 (년)','years',3,'number')}${field('제시 연봉 (만 원)','salary',4500,'number')}<label class="field">고용 형태<select name="type">${options(['정규직','계약직','일용직'],'정규직')}</select></label>${field('상세 근무지','location','경기 수원시')}${field('필요 기술 (쉼표로 구분)','skills','전기설비, 시설관리','text','wide')}<label class="field wide">필요 자격증 (쉼표로 구분)<input name="certs" maxlength="300" placeholder="전기기능사 · 필수가 아니라면 비워두세요"></label><label class="field wide">담당 업무와 원하는 인재상<textarea name="description" required maxlength="2000" placeholder="담당 업무, 사용 장비, 필요한 현장 경험을 적어주세요."></textarea></label></div><div class="form-actions"><button class="primary" type="submit">${icon('plus')}채용 등록하고 매칭 보기</button></div></form>${state.jobs.length?`<section><div class="section-header"><h2>내가 등록한 공고</h2></div><div class="job-list">${state.jobs.map(j=>`<div>${jobCard(j)}<div class="between" style="margin-top:10px"><span class="small muted">내가 등록한 공고</span><button class="text-link" data-delete="${esc(j.id)}">공고 삭제</button></div><div class="candidate-row"><h3>프로필 조건 비교</h3><p>${esc(state.profile.name)} · ${score(j).score}% 일치 · ${esc(score(j).reasons[0])}</p><small class="muted">현재 등록된 내 프로필 1건과 비교한 결과입니다.</small></div></div>`).join('')}</div></section>`:''}`;}
function modal(title,body){document.getElementById('modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="닫기">×</button></div><div class="modal-body">${body}</div>`;document.getElementById('modal').showModal();}
function profileModal(){const p=state.profile;modal('나의 기술 프로필',`<p class="small muted" style="margin-bottom:18px">학력보다 현장에서 쌓은 기술과 경험을 알려주세요.</p><form id="profile-form"><div class="form-grid">${field('이름','name',p.name)}<label class="field">전문 직무<select name="role">${options(roles,p.role)}</select></label>${field('현장 경력 (년)','years',p.years,'number')}<label class="field">희망 지역<select name="region">${options([...regions,'전국'],p.region)}</select></label>${field('희망 연봉 (만 원)','salary',p.salary,'number')}${field('보유 자격증 (쉼표로 구분)','certs',p.certs.join(', '))}${field('보유 기술 (쉼표로 구분)','skills',p.skills.join(', '),'text','wide')}<label class="field wide">현장 경험 소개<textarea name="bio" maxlength="2000">${esc(p.bio)}</textarea></label></div><div class="form-actions"><button type="button" class="secondary" data-action="close">취소</button><button class="primary" type="submit">저장하고 매칭 업데이트</button></div></form>`);document.querySelector('[name="certs"]').required=false;}
function detail(id){const j=jobs().find(x=>x.id===id);if(!j)return;const r=result(j);modal('채용 상세',`<div class="company-name">${esc(j.company)} <span class="local-label">${j.id.startsWith('j')?'예시 공고':'내가 등록한 공고'}</span></div><h2 class="detail-title">${esc(j.title)}</h2><div class="job-meta"><span>${icon('pin')}${esc(j.location)}</span><span>${icon('coin')}연 ${j.salary.toLocaleString()}만 원</span><span>${esc(j.type)}</span></div><div class="detail-block"><h3>담당 업무</h3><p>${esc(j.description)}</p></div><div class="detail-block"><h3>필요한 기술과 자격</h3><div class="tags">${[...j.skills,...j.certs].map(s=>`<span class="tag">${esc(s)}</span>`).join('')}</div></div><div class="detail-block"><h3 class="blue">${icon('sparkles')} ${aiResults?'AI':'조건'} 매칭 ${r.score}%</h3>${r.parts?Object.entries(r.parts).map(([k,v],i)=>`<div class="score-line"><div class="between"><span>${k}</span><span>${v} / ${[35,20,20,15,10][i]}</span></div><div class="progress"><span style="width:${v/[35,20,20,15,10][i]*100}%"></span></div></div>`).join(''):''}<ul class="reasons">${r.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="notice" style="margin-top:20px;margin-bottom:0">관심 지원은 이 브라우저에만 기록되며 기업에 전송되지 않습니다.</div><div class="form-actions"><button class="secondary" data-save="${esc(j.id)}">${state.saved.includes(j.id)?'저장 취소':'채용 저장'}</button><button class="primary" data-apply="${esc(j.id)}">${state.applications.includes(j.id)?'관심 지원 취소':'관심 지원 기록하기'}</button></div>`);}
function invalidate(){aiResults=null;matchRevision++;busy=false;}
async function runMatch(){if(busy)return;if(!apiReady){invalidate();render();toast('최신 프로필로 조건 매칭을 업데이트했어요.');return;}busy=true;const revision=++matchRevision;render();try{const p=state.profile;const res=await fetch('/api/match',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile:{role:p.role,years:p.years,region:p.region,salary:p.salary,skills:p.skills,certs:p.certs,bio:p.bio},jobs:jobs().map(({id,title,role,years,salary,region,skills,certs,description})=>({id,title,role,years,salary,region,skills,certs,description}))}),signal:AbortSignal.timeout(65000)});const data=await res.json();if(!res.ok)throw Error(data.error||'AI 분석에 연결하지 못했습니다.');if(revision!==matchRevision)return;aiResults=data.matches;toast('AI가 채용 조건과 경험을 비교했어요.');}catch(e){if(revision===matchRevision){aiResults=null;toast(`${e.name==='TimeoutError'?'AI 응답 시간이 초과됐습니다.':e.message} 조건 매칭을 표시합니다.`);}}finally{if(revision===matchRevision){busy=false;render();}}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a[data-view]');if(!b)return;if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.filter){filter=b.dataset.filter;render();return;}if(b.dataset.detail){detail(b.dataset.detail);return;}if(b.dataset.delete){const id=b.dataset.delete;if(!state.jobs.some(j=>j.id===id))return;state.jobs=state.jobs.filter(j=>j.id!==id);state.saved=state.saved.filter(x=>x!==id);state.applications=state.applications.filter(x=>x!==id);invalidate();persist();render();toast('등록한 공고를 삭제했어요.');return;}if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();if(document.getElementById('modal').open){document.getElementById('modal').close();detail(id);}return;}if(b.dataset.apply){const id=b.dataset.apply;const exists=state.applications.includes(id);state.applications=exists?state.applications.filter(x=>x!==id):[...state.applications,id];persist();document.getElementById('modal').close();render();toast(exists?'관심 지원을 취소했어요.':'관심 지원을 기록했어요. 기업에 전송되지는 않습니다.');return;}if(b.dataset.like){const id=b.dataset.like;state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];persist();render();return;}if(b.dataset.comments){const el=document.getElementById(`comments-${b.dataset.comments}`);el.hidden=!el.hidden;if(!el.hidden)el.querySelector('input').focus();return;}if(b.dataset.action==='profile')profileModal();if(b.dataset.action==='close')document.getElementById('modal').close();if(b.dataset.action==='match')runMatch();if(b.dataset.action==='write')modal('현장 이야기 쓰기','<form id="post-form"><label class="field">나누고 싶은 경험<textarea name="text" maxlength="3000" required placeholder="현장의 노하우, 오늘의 성취, 동료에게 전할 이야기를 남겨주세요."></textarea></label><div class="form-actions"><button type="submit" class="primary">이야기 등록</button></div></form>');});
const split=s=>[...new Set(String(s).split(/[,，]/).map(x=>x.trim()).filter(Boolean))].slice(0,30);
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;const d=Object.fromEntries(new FormData(f));if(f.id==='profile-form'){if(!d.name.trim()||!split(d.skills).length){toast('이름과 기술을 입력해 주세요.');return;}state.profile={...d,name:d.name.trim(),years:Math.min(80,Number(d.years)),salary:Number(d.salary),skills:split(d.skills),certs:split(d.certs)};invalidate();persist();document.getElementById('modal').close();render();toast('프로필을 저장하고 조건 매칭을 업데이트했어요.');}else if(f.id==='employer-form'){if(!d.company.trim()||!d.title.trim()||!d.description.trim()||!split(d.skills).length){toast('기업명, 제목, 기술, 담당 업무를 입력해 주세요.');return;}const j={...d,id:`u${Date.now()}`,company:d.company.trim(),title:d.title.trim(),years:Number(d.years),salary:Number(d.salary),skills:split(d.skills),certs:split(d.certs),logo:d.company.slice(0,2),color:'#265ee8',bg:'#edf2ff',tags:['신규 등록'],deadline:'상시 채용'};if(state.jobs.length>=40){toast('로컬 데모는 최대 40개 공고를 등록할 수 있어요.');return;}state.jobs.unshift(j);invalidate();persist();render();toast('채용을 등록했어요. 아래에서 프로필 매칭을 확인하세요.');document.querySelector('.candidate-row')?.scrollIntoView({behavior:'smooth',block:'center'});}else if(f.id==='post-form'){if(!d.text.trim())return;state.posts.unshift({id:`u${Date.now()}`,author:state.profile.name,role:state.profile.role+' · 나의 현장 이야기',text:d.text.trim(),likes:0});persist();document.getElementById('modal').close();render();toast('현장 이야기를 저장했어요.');}else if(f.dataset.commentForm){if(!d.comment.trim())return;const id=f.dataset.commentForm;state.comments[id]=[...(state.comments[id]||[]),{author:state.profile.name,text:d.comment.trim()}];persist();render();document.getElementById(`comments-${id}`).hidden=false;}});
document.getElementById('search').addEventListener('input',e=>{query=e.target.value;view='jobs';history.replaceState(null,'','#jobs');render();});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['home','jobs','match','community','saved','applications','employer'].includes(v)){view=v;filter='전체';render();}});
document.getElementById('modal').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close();}});
render();if(location.protocol!=='file:')fetch('/api/config').then(r=>r.ok?r.json():null).then(c=>{apiReady=!!c?.aiEnabled;if(view==='match')render();}).catch(()=>{});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_bluein_jobs',title:'블루인 채용 검색',description:'현재 브라우저에 있는 채용을 검색하고 채용 화면을 표시합니다.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:120}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>120)throw Error('검색어를 120자 이내로 입력하세요.');view='jobs';filter='전체';query=input.query;document.getElementById('search').value=query;history.replaceState(null,'','#jobs');render();return {jobs:filtered().map(j=>({id:j.id,title:j.title,score:j.result.score}))};}})).catch(()=>{});}catch{}}
